package org.jsoup.safety;

import java.io.*;
import java.math.*;
import java.util.*;
import org.jsoup.helper.Validate;
import org.jsoup.nodes.Attribute;
import org.jsoup.nodes.Attributes;
import org.jsoup.nodes.DataNode;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.jsoup.nodes.Node;
import org.jsoup.nodes.TextNode;
import org.jsoup.parser.ParseErrorList;
import org.jsoup.parser.Parser;
import org.jsoup.parser.Tag;
import org.jsoup.safety.Whitelist;
import org.jsoup.select.NodeTraversor;
import org.jsoup.select.NodeVisitor;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.junit.runners.JUnit4;
import static org.junit.Assert.*;

@RunWith(JUnit4.class)
public class Cleaner_isValid_TriageGen2Test {

    private Cleaner cleaner;

    @Before
    public void setup() {
        cleaner = new Cleaner(new Whitelist());
    }

    @Test
    public void testIsValid_withValidDocument_returnsTrue() {
        // Arrange
        Document dirtyDocument = new Document("<html><body></body></html>");

        // Act
        boolean isValid = cleaner.isValid(dirtyDocument);

        // Assert
        assertTrue(isValid);
    }

    @Test
    public void testIsValid_withInvalidDocument_returnsFalse() {
        // Arrange
        Document dirtyDocument = new Document("<html><body><script>alert('xss')</script></body></html>");

        // Act
        boolean isValid = cleaner.isValid(dirtyDocument);

        // Assert
        assertFalse(isValid);
    }

    @Test
    public void testIsValid_withNullDocument_throwsNullPointerException() {
        // Act and Assert
        try {
            cleaner.isValid(null);
            fail("Expected NullPointerException");
        } catch (NullPointerException e) {
            // Expected
        }
    }

    @Test
    public void testIsValid_withDocumentWithBaseUri_returnsTrue() {
        // Arrange
        Document dirtyDocument = new Document("<html><body></body></html>");
        dirtyDocument.baseUri("http://example.com");

        // Act
        boolean isValid = cleaner.isValid(dirtyDocument);

        // Assert
        assertTrue(isValid);
    }

    @Test
    public void testIsValid_withDocumentWithBaseUriAndScriptTag_returnsFalse() {
        // Arrange
        Document dirtyDocument = new Document("<html><body><script>alert('xss')</script></body></html>");
        dirtyDocument.baseUri("http://example.com");

        // Act
        boolean isValid = cleaner.isValid(dirtyDocument);

        // Assert
        assertFalse(isValid);
    }

    @Test
    public void testIsValid_withDocumentWithMultipleScriptTags_returnsFalse() {
        // Arrange
        Document dirtyDocument = new Document("<html><body><script>alert('xss')</script><script>alert('xss')</script></body></html>");

        // Act
        boolean isValid = cleaner.isValid(dirtyDocument);

        // Assert
        assertFalse(isValid);
    }

    @Test
    public void testIsValid_withDocumentWithCommentTag_returnsTrue() {
        // Arrange
        Document dirtyDocument = new Document("<html><body><!-- comment --></body></html>");

        // Act
        boolean isValid = cleaner.isValid(dirtyDocument);

        // Assert
        assertTrue(isValid);
    }

    @Test
    public void testIsValid_withDocumentWithEmptyBody_returnsTrue() {
        // Arrange
        Document dirtyDocument = new Document("<html><body></body></html>");

        // Act
        boolean isValid = cleaner.isValid(dirtyDocument);

        // Assert
        assertTrue(isValid);
    }

    @Test
    public void testIsValid_withDocumentWithInvalidCharacter_returnsFalse() {
        // Arrange
        Document dirtyDocument = new Document("<html><body><script>alert('xss')</script><&#x00a0;></body></html>");

        // Act
        boolean isValid = cleaner.isValid(dirtyDocument);

        // Assert
        assertFalse(isValid);
    }
}
